// Generated by Kargo: bundles a browser app with `bun build`'s API. The only argument is the JSON file of options.
import { readFileSync, writeFileSync } from 'node:fs';
import { isAbsolute, relative, resolve, sep } from 'node:path';

const options = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const replacements = options.replace.map((r) => ({ dir: resolve(r.dir), from: r.from, to: r.to }));

// Whether `file` is one of the compiler's modules in `dir`: below it, but not in a package.
const inside = (file, dir) => {
  const rel = relative(dir, file);
  return rel !== '' && !rel.startsWith('..') && !isAbsolute(rel) && !rel.split(sep).includes('node_modules');
};

// Rewrites the names of files the bundler cannot see, such as the `.wasm` file a Kotlin/Wasm module fetches.
const rewrite = {
  name: 'kargo-rewrite',
  setup(build) {
    build.onLoad({ filter: /\.m?js$/ }, async (args) => {
      const mine = replacements.filter((r) => inside(resolve(args.path), r.dir));
      if (mine.length === 0) return undefined;
      const text = await Bun.file(args.path).text();
      let contents = text;
      for (const r of mine) contents = contents.split(r.from).join(r.to);
      return contents === text ? undefined : { contents, loader: 'js' };
    });
  },
};

try {
  const result = await Bun.build({
    entrypoints: [options.input],
    outdir: options.outDir,
    target: 'browser',
    format: 'esm',
    splitting: true,
    minify: options.minify,
    sourcemap: options.sourceMaps ? 'linked' : 'none',
    external: options.external.flatMap((name) => [name, `${name}/*`]),
    naming: { entry: '[name]-[hash].[ext]', chunk: 'chunk-[hash].[ext]', asset: '[name]-[hash].[ext]' },
    plugins: [rewrite],
  });
  if (!result.success) {
    for (const log of result.logs) console.error(String(log.message ?? log));
    process.exit(1);
  }
  const entry = result.outputs.find((output) => output.kind === 'entry-point');
  if (!entry) {
    console.error('bun build wrote no entry point');
    process.exit(1);
  }
  writeFileSync(options.manifest, JSON.stringify({ entry: relative(options.outDir, entry.path).split(sep).join('/') }));
} catch (error) {
  for (const log of error.errors ?? [error]) console.error(String(log.message ?? log));
  process.exit(1);
}
